package local.tv.quranidle;
import android.app.*;import android.content.*;import android.graphics.Color;import android.graphics.PixelFormat;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import android.util.Log;import org.json.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.Locale;
final class PrayerNotice {
 private final AdhanPlayer adhanPlayer;private final Service c;private final Handler h=new Handler(Looper.getMainLooper());private final android.content.SharedPreferences prefs;private final AlarmManager alarms;private final PendingIntent alarm;private final WindowManager wm;private TextView banner;private boolean fetching,closed,preview;private String loadedDay="";
 private static final ZoneId Z=ZoneId.of("Asia/Riyadh");private static final long OFFSET=7*60000L,LENGTH=20*60000L;private static final String[] KEYS={"Fajr","Dhuhr","Asr","Maghrib","Isha"};
 private final BroadcastReceiver changed=new BroadcastReceiver(){public void onReceive(Context x,Intent i){refresh();check();}};
 private final Runnable refreshTick=new Runnable(){public void run(){refresh();check();h.postDelayed(this,3600000);}};
 PrayerNotice(Service service){c=service;adhanPlayer=new AdhanPlayer(service);prefs=c.getSharedPreferences("prayers",0);alarms=c.getSystemService(AlarmManager.class);wm=c.getSystemService(WindowManager.class);alarm=PendingIntent.getBroadcast(c,41,new Intent(c,PrayerAlarmReceiver.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);IntentFilter f=new IntentFilter();f.addAction(Intent.ACTION_TIME_CHANGED);f.addAction(Intent.ACTION_TIMEZONE_CHANGED);f.addAction(Intent.ACTION_DATE_CHANGED);c.registerReceiver(changed,f,Context.RECEIVER_EXPORTED);h.post(refreshTick);}
 void refresh(){String day=LocalDate.now(Z).toString();if(fetching||day.equals(loadedDay))return;fetching=true;new Thread(()->{boolean ok=true;for(int n=0;n<2;n++){LocalDate d=LocalDate.now(Z).plusDays(n);String k=d.toString();if(prefs.contains(k))continue;java.net.HttpURLConnection net=null;try{String date=d.format(DateTimeFormatter.ofPattern("dd-MM-yyyy",Locale.ROOT));net=(java.net.HttpURLConnection)new java.net.URL("https://api.aladhan.com/v1/timings/"+date+"?latitude=26.3260&longitude=43.9750&method=4&timezonestring=Asia%2FRiyadh").openConnection();net.setConnectTimeout(10000);net.setReadTimeout(10000);String body;try(java.io.InputStream in=net.getInputStream();java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] b=new byte[4096];for(int r;(r=in.read(b))>0;)out.write(b,0,r);body=out.toString("UTF-8");}JSONObject t=new JSONObject(body).getJSONObject("data").getJSONObject("timings");for(String key:KEYS)LocalTime.parse(t.getString(key).substring(0,5));prefs.edit().putString(k,t.toString()).apply();}catch(Exception e){ok=false;Log.w("PrayerNotice","fetch-failed-"+e.getClass().getSimpleName());}finally{if(net!=null)net.disconnect();}}final boolean success=ok;h.post(()->{if(closed)return;fetching=false;if(success)loadedDay=day;Log.i("PrayerNotice","times-ready="+success);check();});},"PrayerTimesFetch").start();}
 void check(){if(closed||preview)return;long now=System.currentTimeMillis(),next=Long.MAX_VALUE,end=0;for(int n=-1;n<=1;n++){LocalDate day=LocalDate.now(Z).plusDays(n);try{JSONObject t=new JSONObject(prefs.getString(day.toString(),"{}"));for(String key:KEYS){LocalTime time=LocalTime.parse(t.getString(key).substring(0,5));long adhan=day.atTime(time).atZone(Z).toInstant().toEpochMilli();if(adhan>now)next=Math.min(next,adhan);if(now>=adhan&&now<adhan+120000&&prefs.getLong("last_adhan",0)!=adhan){prefs.edit().putLong("last_adhan",adhan).apply();adhanPlayer.play("Fajr".equals(key),false);}long start=adhan+OFFSET;long finish=start+LENGTH;if(now>=start&&now<finish)end=Math.max(end,finish);if(start>now)next=Math.min(next,start);if(finish>now)next=Math.min(next,finish);}}catch(Exception ignored){}}
 if(end>now){show(end);Log.i("PrayerNotice","notice-active-until-"+end);}else hide();alarms.cancel(alarm);if(next<Long.MAX_VALUE){try{if(alarms.canScheduleExactAlarms())alarms.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,next,alarm);else{alarms.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,next,alarm);Log.w("PrayerNotice","exact-alarm-not-granted");}}catch(Exception e){Log.w("PrayerNotice","alarm-failed");}Log.i("PrayerNotice","next-boundary-"+next);}if(end>now)h.postDelayed(()->check(),Math.min(60000,end-now));}
 private void show(long until){PrayerGuard.begin(c,until);if(banner!=null)return;if(!Settings.canDrawOverlays(c)){Log.e("PrayerNotice","overlay-permission-missing");return;}banner=new TextView(c);banner.setText("وقت الصلاة الآن");banner.setTextColor(Color.WHITE);banner.setTextSize(52);banner.setLetterSpacing(0);banner.setTypeface(android.graphics.Typeface.create("sans-serif",android.graphics.Typeface.BOLD));banner.setGravity(Gravity.CENTER);int pad=dp(18);banner.setPadding(pad,pad,pad,pad);GradientDrawable bg=new GradientDrawable();bg.setColor(0xFF153C31);bg.setCornerRadius(0);banner.setBackground(bg);WindowManager.LayoutParams lp=new WindowManager.LayoutParams(-1,-1,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.CENTER;lp.y=0;banner.setFocusableInTouchMode(true);banner.setOnKeyListener((v,key,event)->PrayerGuard.active(c)&&key!=KeyEvent.KEYCODE_POWER);try{wm.addView(banner,lp);banner.requestFocus();Log.i("PrayerNotice","banner-visible");}catch(Exception e){banner=null;Log.e("PrayerNotice","overlay-failed",e);}}
 private void hide(){PrayerGuard.end(c);if(banner!=null){try{wm.removeView(banner);}catch(Exception ignored){}banner=null;Log.i("PrayerNotice","banner-hidden");}}
 void preview(){preview=true;show(System.currentTimeMillis()+30000);Log.i("PrayerNotice","preview-30-seconds");h.postDelayed(()->{preview=false;hide();check();},30000);}
 private int dp(int n){return Math.round(n*c.getResources().getDisplayMetrics().density);}
 void testAdhan(){adhanPlayer.play(false,true);}
 void close(){adhanPlayer.close();closed=true;h.removeCallbacksAndMessages(null);hide();alarms.cancel(alarm);c.unregisterReceiver(changed);}
}


